<?php
include_once __DIR__.'/includes/session_check.php';require_login_modal();include __DIR__.'/db_connect.php';$school=(int)($_SESSION['login_school_id']??0);if(!$school)die('No autorizado.');$autoload=__DIR__.'/vendor/autoload.php';if(!file_exists($autoload))die('PhpSpreadsheet no está instalado.');require_once $autoload;
use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use PhpOffice\PhpSpreadsheet\Style\Fill;
function edrBind(mysqli_stmt $s,string $t,array &$p):void{if($t==='')return;$a=[$t];foreach($p as &$v)$a[]=&$v;call_user_func_array([$s,'bind_param'],$a);}
$where=['s.school_id=?'];$types='i';$params=[$school];$add=function($sql,$type,$value)use(&$where,&$types,&$params){if($value===''||$value===0)return;$where[]=$sql;$types.=$type;$params[]=$value;};$add('c.academic_year_id=?','i',(int)($_GET['academic_year_id']??0));$add('s.id=?','i',(int)($_GET['student_id']??0));$add('s.nivel=?','s',trim($_GET['nivel']??''));$add('s.grado=?','s',trim($_GET['grado']??''));$add('s.seccion=?','s',trim($_GET['seccion']??''));$add('ef.course_id=?','i',(int)($_GET['concepto']??0));$add('s.status=?','s',trim($_GET['student_status']??''));$add('ef.debt_status=?','s',trim($_GET['debt_status']??''));$dateType=trim($_GET['date_type']??'assignment');$from=trim($_GET['start_date']??'');$to=trim($_GET['end_date']??'');if($dateType==='payment'){if($from){$where[]="EXISTS(SELECT 1 FROM payments pd WHERE pd.ef_id=ef.id AND COALESCE(pd.payment_status,'Confirmado')='Confirmado' AND DATE(pd.date_created)>=?)";$types.='s';$params[]=$from;}if($to){$where[]="EXISTS(SELECT 1 FROM payments pd WHERE pd.ef_id=ef.id AND COALESCE(pd.payment_status,'Confirmado')='Confirmado' AND DATE(pd.date_created)<=?)";$types.='s';$params[]=$to;}}else{$col=$dateType==='due'?'ef.due_date':'COALESCE(ef.issue_date,DATE(ef.date_created))';if($from){$where[]="$col>=?";$types.='s';$params[]=$from;}if($to){$where[]="$col<=?";$types.='s';$params[]=$to;}}
$base="SELECT ef.id,ef.total_fee,ef.discounted_amount,ef.debt_status,ef.issue_date,ef.due_date,ef.billing_period,ef.cancellation_reason,s.id_no,s.name,s.nivel,s.grado,s.seccion,s.status student_status,c.course,ay.year,COALESCE(ef.discounted_amount,ef.total_fee) effective,(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.ef_id=ef.id AND COALESCE(p.payment_status,'Confirmado')='Confirmado') paid FROM student_ef_list ef INNER JOIN student s ON s.id=ef.student_id INNER JOIN courses c ON c.id=ef.course_id LEFT JOIN academic_year ay ON ay.id=c.academic_year_id WHERE ".implode(' AND ',$where);$state="CASE WHEN q.debt_status='Anulada' THEN 'Anulada' WHEN q.debt_status='Suspendida' THEN 'Suspendida' WHEN q.discounted_amount IS NOT NULL AND q.total_fee>0 AND q.effective<=0.009 THEN 'Exonerada' WHEN q.effective>0 AND q.paid+0.009>=q.effective THEN 'Pagada' WHEN q.paid>0 THEN 'Parcial' WHEN q.due_date IS NOT NULL AND q.due_date<CURDATE() THEN 'Vencida' ELSE 'Pendiente' END";$financial=trim($_GET['financial_status']??'Con deuda');$outer='';if($financial==='Con deuda'){$outer=" WHERE q.debt_status='Activa' AND q.effective-q.paid>0.009";}elseif(in_array($financial,['Pendiente','Parcial','Pagada','Exonerada','Vencida','Suspendida','Anulada'],true)){$outer=" WHERE $state=?";$types.='s';$params[]=$financial;}$stmt=$conn->prepare("SELECT q.*,GREATEST(0,q.effective-q.paid) balance,$state financial_state FROM ($base) q$outer ORDER BY q.year DESC,q.name,q.course");edrBind($stmt,$types,$params);$stmt->execute();$r=$stmt->get_result();
$book=new Spreadsheet();$sheet=$book->getActiveSheet();$sheet->setTitle('Reporte de deudas');$headers=['Año','DNI','Estudiante','Nivel','Grado','Sección','Concepto','Periodo','Asignación','Vencimiento','Original','Descuento','Exigible','Pagado confirmado','Saldo','Estado financiero','Estado deuda','Estado estudiante'];$sheet->fromArray($headers,null,'A1');$sheet->getStyle('A1:R1')->getFont()->setBold(true)->getColor()->setARGB('FFFFFFFF');$sheet->getStyle('A1:R1')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('FF2F6FED');$row=2;while($x=$r->fetch_assoc()){$discount=max(0,(float)$x['total_fee']-(float)$x['effective']);$sheet->fromArray([$x['year'],$x['id_no'],$x['name'],$x['nivel'],$x['grado'],$x['seccion'],$x['course'],$x['billing_period'],$x['issue_date'],$x['due_date'],(float)$x['total_fee'],$discount,(float)$x['effective'],(float)$x['paid'],(float)$x['balance'],$x['financial_state'],$x['debt_status'],$x['student_status']],null,'A'.$row++);}foreach(range('A','R')as$c)$sheet->getColumnDimension($c)->setAutoSize(true);$sheet->freezePane('A2');$sheet->setAutoFilter('A1:R'.max(1,$row-1));while(ob_get_level())ob_end_clean();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="reporte_deudas_'.date('Ymd_His').'.xlsx"');header('Cache-Control: max-age=0');(new Xlsx($book))->save('php://output');exit;
